import{_ as a,c as r,o as i,ag as t}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Research Preparation","description":"","frontmatter":{"title":"Research Preparation"},"headers":[],"relativePath":"research/research-preparation.md","filePath":"research/research-preparation.md","lastUpdated":null}'),n={name:"research/research-preparation.md"};function o(s,e,l,c,h,d){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="research-preparation" tabindex="-1">Research Preparation <a class="header-anchor" href="#research-preparation" aria-label="Permalink to &quot;Research Preparation&quot;">​</a></h1><h2 id="plan-and-prepare-for-research" tabindex="-1">Plan and Prepare for Research <a class="header-anchor" href="#plan-and-prepare-for-research" aria-label="Permalink to &quot;Plan and Prepare for Research&quot;">​</a></h2><h3 id="plan-for-research" tabindex="-1">Plan for Research <a class="header-anchor" href="#plan-for-research" aria-label="Permalink to &quot;Plan for Research&quot;">​</a></h3><p><a href="/research/research-template.html">templates</a> are available for community members to use and edit.</p><h3 id="understanding-the-topic-or-tasks" tabindex="-1">Understanding the Topic or Tasks <a class="header-anchor" href="#understanding-the-topic-or-tasks" aria-label="Permalink to &quot;Understanding the Topic or Tasks&quot;">​</a></h3><h2 id="clearly-define-the-research-topic-or-tasks-to-ensure-the-team-is-aligned-on-goals-and-deliverables" tabindex="-1">Clearly define the research topic or tasks to ensure the team is aligned on goals and deliverables. <a class="header-anchor" href="#clearly-define-the-research-topic-or-tasks-to-ensure-the-team-is-aligned-on-goals-and-deliverables" aria-label="Permalink to &quot;Clearly define the research topic or tasks to ensure the team is aligned on goals and deliverables.&quot;">​</a></h2><h2 id="this-could-involve-brainstorming-sessions-or-mind-mapping-to-explore-different-aspects-of-the-research" tabindex="-1">This could involve brainstorming sessions or mind mapping to explore different aspects of the research. <a class="header-anchor" href="#this-could-involve-brainstorming-sessions-or-mind-mapping-to-explore-different-aspects-of-the-research" aria-label="Permalink to &quot;This could involve brainstorming sessions or mind mapping to explore different aspects of the research.&quot;">​</a></h2><h2 id="confirm-the-scope-of-the-research-and-the-specific-questions-or-problems-that-need-to-be-answered-e-g-identifying-a-company-s-center-of-gravity-understanding-a-target-audience-or-analyzing-a-network-for-vulnerabilities" tabindex="-1">Confirm the scope of the research and the specific questions or problems that need to be answered (e.g., identifying a company’s center of gravity, understanding a target audience, or analyzing a network for vulnerabilities). <a class="header-anchor" href="#confirm-the-scope-of-the-research-and-the-specific-questions-or-problems-that-need-to-be-answered-e-g-identifying-a-company-s-center-of-gravity-understanding-a-target-audience-or-analyzing-a-network-for-vulnerabilities" aria-label="Permalink to &quot;Confirm the scope of the research and the specific questions or problems that need to be answered (e.g., identifying a company’s center of gravity, understanding a target audience, or analyzing a network for vulnerabilities).&quot;">​</a></h2><h3 id="identify-the-scope-of-the-research" tabindex="-1">Identify the Scope of the Research <a class="header-anchor" href="#identify-the-scope-of-the-research" aria-label="Permalink to &quot;Identify the Scope of the Research&quot;">​</a></h3><h2 id="define-the-boundaries-of-the-research-including-geographical-area-time-frame-and-specific-aspects-of-the-topic-to-be-covered" tabindex="-1">Define the boundaries of the research, including geographical area, time frame, and specific aspects of the topic to be covered. <a class="header-anchor" href="#define-the-boundaries-of-the-research-including-geographical-area-time-frame-and-specific-aspects-of-the-topic-to-be-covered" aria-label="Permalink to &quot;Define the boundaries of the research, including geographical area, time frame, and specific aspects of the topic to be covered.&quot;">​</a></h2><h2 id="determine-specific-objectives-such-as-identifying-key-players-understanding-behaviors-or-forecasting-risks" tabindex="-1">Determine specific objectives such as identifying key players, understanding behaviors, or forecasting risks. <a class="header-anchor" href="#determine-specific-objectives-such-as-identifying-key-players-understanding-behaviors-or-forecasting-risks" aria-label="Permalink to &quot;Determine specific objectives such as identifying key players, understanding behaviors, or forecasting risks.&quot;">​</a></h2><h2 id="identify-research-limitations-like-data-availability-ethical-considerations-or-resource-constraints" tabindex="-1">Identify research limitations like data availability, ethical considerations, or resource constraints. <a class="header-anchor" href="#identify-research-limitations-like-data-availability-ethical-considerations-or-resource-constraints" aria-label="Permalink to &quot;Identify research limitations like data availability, ethical considerations, or resource constraints.&quot;">​</a></h2><h2 id="define-the-research-questions-guiding-the-data-collection-and-analysis-process" tabindex="-1">Define the research questions guiding the data collection and analysis process. <a class="header-anchor" href="#define-the-research-questions-guiding-the-data-collection-and-analysis-process" aria-label="Permalink to &quot;Define the research questions guiding the data collection and analysis process.&quot;">​</a></h2><h3 id="identifying-necessary-data" tabindex="-1">Identifying Necessary Data <a class="header-anchor" href="#identifying-necessary-data" aria-label="Permalink to &quot;Identifying Necessary Data&quot;">​</a></h3><ul><li><p><strong>Type of Data</strong>: Determine whether qualitative, quantitative, or a mix of both is needed. This decision will influence data collection methods.</p></li><li><p><strong>Sources of Data</strong>: List potential sources like public databases, surveys, interviews, or experimental data.</p><ul><li>See the <a href="/general/rstudio.html">Guide</a> for valuable datasets.</li></ul></li></ul><h3 id="developing-a-collection-strategy" tabindex="-1">Developing a Collection Strategy <a class="header-anchor" href="#developing-a-collection-strategy" aria-label="Permalink to &quot;Developing a Collection Strategy&quot;">​</a></h3><ul><li><p><strong>Methods</strong>: Choose appropriate data collection methods like surveys, web scraping, direct observation, or experiments.</p></li><li><p><strong>Tools</strong>: Identify any software or tools required for the collection, such as survey platforms or data logging equipment.</p></li><li><p><strong>Ethical Considerations</strong>: Address ethical implications, especially for human subjects, ensuring consent or ethics board approval if needed.</p></li></ul><h3 id="formulating-hypotheses" tabindex="-1">Formulating Hypotheses <a class="header-anchor" href="#formulating-hypotheses" aria-label="Permalink to &quot;Formulating Hypotheses&quot;">​</a></h3><ul><li><p>Null Hypothesis: &quot;The content shows no significant signs of being AI-generated.&quot;</p></li><li><p>Alternative Hypothesis: &quot;The content shows significant signs of being AI-generated.&quot;</p></li></ul><p>Structured Analytical Techniques (SATs), such as Analysis of Competing Hypotheses (ACH) and Key Assumptions Check (KAC), help refine hypotheses. Use the <a href="/general/structured-analytic-techniques-sats.html">wiki page</a> to guide planning, brainstorming, data collection, and analysis.</p><h3 id="prepare-for-research" tabindex="-1">Prepare for Research <a class="header-anchor" href="#prepare-for-research" aria-label="Permalink to &quot;Prepare for Research&quot;">​</a></h3><h3 id="operationalizing-variables" tabindex="-1">Operationalizing Variables <a class="header-anchor" href="#operationalizing-variables" aria-label="Permalink to &quot;Operationalizing Variables&quot;">​</a></h3><ul><li><p><strong>Identifying Indicators</strong>: Decide on themes or patterns to look for in qualitative data and specific metrics for quantitative data.</p></li><li><p><strong>Measurement Scale</strong>: Establish if data is nominal, ordinal, interval, or ratio to guide the analysis.</p></li></ul><h3 id="ensuring-data-quality" tabindex="-1">Ensuring Data Quality <a class="header-anchor" href="#ensuring-data-quality" aria-label="Permalink to &quot;Ensuring Data Quality&quot;">​</a></h3><ul><li><p><strong>Pilot Testing</strong>: Conduct trial runs to ensure the reliability and validity of data collection methods.</p></li><li><p><strong>Training Data Collectors</strong>: Train team members to minimize errors and ensure consistency.</p></li><li><p><strong>Standardizing Data Entry</strong>: Create a standardized format for data entry to streamline processing and analysis.</p></li></ul><h3 id="data-management-plan" tabindex="-1">Data Management Plan <a class="header-anchor" href="#data-management-plan" aria-label="Permalink to &quot;Data Management Plan&quot;">​</a></h3><ul><li><p><strong>Data Storage</strong>: Establish secure storage solutions accessible for analysis while respecting ethical considerations.</p></li><li><p><strong>Data Processing Procedures</strong>: Define how data will be cleaned and prepared for analysis, including how to handle missing data.</p></li><li><p><strong>Version Control</strong>: Implement a version control system for datasets to manage updates and collaboration.</p></li></ul><h3 id="team-collaboration" tabindex="-1">Team Collaboration <a class="header-anchor" href="#team-collaboration" aria-label="Permalink to &quot;Team Collaboration&quot;">​</a></h3><ul><li><p><strong>Communication Channels</strong>: Set up regular meetings and communication protocols to keep the team informed.</p></li><li><p><strong>Role Definition</strong>: Clarify roles and responsibilities in data collection and analysis.</p></li><li><p><strong>Documentation</strong>: Maintain detailed records of data collection, issues, and resolutions.</p></li></ul><h3 id="preparing-systems-and-devices-for-research" tabindex="-1">Preparing Systems and Devices for Research <a class="header-anchor" href="#preparing-systems-and-devices-for-research" aria-label="Permalink to &quot;Preparing Systems and Devices for Research&quot;">​</a></h3><p>Setting up devices and accounts for research is important for privacy, security, and obtaining unbiased results. Use the following resources to secure your workstation.</p><h4 id="virtual-machine-for-research" tabindex="-1">Virtual Machine for Research <a class="header-anchor" href="#virtual-machine-for-research" aria-label="Permalink to &quot;Virtual Machine for Research&quot;">​</a></h4><p>Virtual Machines or containerization improve security and privacy by isolating the research environment from the host system. See <a href="/general/virtual-environments.html">Up a Research Virtual Machine</a> for more details.</p><h4 id="virtual-private-network-vpn-for-research" tabindex="-1">Virtual Private Network (VPN) for Research <a class="header-anchor" href="#virtual-private-network-vpn-for-research" aria-label="Permalink to &quot;Virtual Private Network (VPN) for Research&quot;">​</a></h4><p>A VPN can protect privacy while researching and help bypass website geographic restrictions. Check the <a href="/privacy/vpn-recommendation.html">community VPN guide</a> to choose the right VPN for your research.</p><h3 id="kasm-virtual-environment" tabindex="-1">Kasm Virtual Environment <a class="header-anchor" href="#kasm-virtual-environment" aria-label="Permalink to &quot;Kasm Virtual Environment&quot;">​</a></h3><p>Kasm allows you to run a virtual machine in a web browser, useful for research on devices without local resources. Find the self-hosted version of Kasm [</p><h3 id="pre-browsing-checks" tabindex="-1">Pre-Browsing Checks <a class="header-anchor" href="#pre-browsing-checks" aria-label="Permalink to &quot;Pre-Browsing Checks&quot;">​</a></h3><p>Run the following checks before browsing to ensure privacy and security:</p><ol><li><p><a href="/general/links.html">https://dnsleaktest.com/ DNS / IP Leak Test</a>.) - Confirm your location.</p></li><li><p><a href="https://coveryourtracks.eff.org/" target="_blank" rel="noreferrer">Cover Your Tracks EFF</a> - Browser canvas check.</p></li><li><p><a href="https://www.grc.com/cookies/forensics.html" target="_blank" rel="noreferrer">Browser Cookie Tester</a></p></li><li><p><a href="https://inappbrowser.com/" target="_blank" rel="noreferrer">InAppBrowser</a></p></li><li><p><a href="https://canyoublockit.com/extreme-test/" target="_blank" rel="noreferrer">AdBlock Test</a> - Ensure ads are blocked.</p></li></ol><p>See the full <a href="/general/dfp-guide.html">Force Protection Guide</a> for more detailed guidance.</p><p>[Collection] [Collaboration]</p>',42)])])}const f=a(n,[["render",o]]);export{u as __pageData,f as default};
